// Command gmp-config-gen generates Google Managed Prometheus (GMP)
// PodMonitoring assets from the CoreOS ServiceMonitor and PodMonitor assets
// reconciled by the control-plane-operator v2 component framework.
//
// The CoreOS monitors are the source of truth. Whenever one changes, the
// corresponding GMP PodMonitoring must change with it. Generated files live
// outside the active CPO asset tree until a gated reconciler loads them. `make generate-gmp-config` regenerates the assets and
// `make verify-gmp-config` fails when the committed assets are stale.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"sort"
)

const (
	// assetsRelPath is the component asset root relative to the repository root.
	assetsRelPath    = "control-plane-operator/controllers/hostedcontrolplane/v2/assets"
	generatedRelPath = "control-plane-operator/controllers/hostedcontrolplane/v2/gmpassets"

	// sourceServiceMonitor is the CoreOS monitor file that selects Services.
	sourceServiceMonitor = "servicemonitor.yaml"
	// sourcePodMonitor is the CoreOS monitor file that selects Pods.
	sourcePodMonitor = "podmonitor.yaml"
	// generatedPodMonitoring is the GMP output file.
	generatedPodMonitoring = "podmonitoring.yaml"

	// generatedHeader marks a file as owned by this generator.
	generatedHeader = "# Code generated by hack/gmp-config-gen; DO NOT EDIT.\n\n"
)

// excludedComponents lists the component asset directories that have a CoreOS
// monitor but must not get a generated GMP PodMonitoring, with the reason.
//
// GMP monitoring is only enabled on GKE management clusters hosting GCP
// HostedClusters, so the generator covers the components shared across
// platforms. Components that only run on other platforms are excluded here.
// Every excluded scrape target needs a matching waiver in
// test/parity/gmpmonitoring/waivers.yaml, so this list and the waivers cannot
// drift apart silently.
var excludedComponents = map[string]string{
	"karpenter":          "AWS and Azure only (AutoNode Karpenter provisioner)",
	"karpenter-operator": "AWS and Azure only (AutoNode Karpenter provisioner)",
}

func main() {
	verify := flag.Bool("verify", false, "verify that the generated assets are committed instead of writing them")
	root := flag.String("root", "", "repository root (defaults to the directory holding go.mod)")
	flag.Parse()

	repoRoot, err := resolveRepoRoot(*root)
	if err != nil {
		fatal(err)
	}

	result, err := generateAll(filepath.Join(repoRoot, assetsRelPath), filepath.Join(repoRoot, generatedRelPath), excludedComponents)
	if err != nil {
		fatal(err)
	}

	if *verify {
		verifyResult(result)
		return
	}
	writeResult(result)
}

func fatal(err error) {
	fmt.Fprintf(os.Stderr, "gmp-config-gen: %v\n", err)
	os.Exit(1)
}

// resolveRepoRoot returns the nearest ancestor of dir that contains go.mod.
func resolveRepoRoot(dir string) (string, error) {
	if dir == "" {
		cwd, err := os.Getwd()
		if err != nil {
			return "", err
		}
		dir = cwd
	}
	absolute, err := filepath.Abs(dir)
	if err != nil {
		return "", err
	}
	for {
		if _, err := os.Stat(filepath.Join(absolute, "go.mod")); err == nil {
			return absolute, nil
		}
		parent := filepath.Dir(absolute)
		if parent == absolute {
			return "", fmt.Errorf("could not find go.mod above %s", dir)
		}
		absolute = parent
	}
}

// generationResult holds every generated file keyed by absolute path, plus the
// generated files that no longer have a CoreOS source.
type generationResult struct {
	generated map[string][]byte
	stale     []string
}

// generateAll generates the PodMonitoring for every component with a CoreOS
// monitor, except the excluded components. A component without a CoreOS monitor
// may own a hand-written PodMonitoring (for example a GCP-only controller); it is
// left untouched.
func generateAll(assetsDir, generatedDir string, excluded map[string]string) (*generationResult, error) {
	if filepath.Clean(assetsDir) == filepath.Clean(generatedDir) {
		return nil, fmt.Errorf("generated GMP assets must be outside the active CPO asset directory")
	}
	entries, err := os.ReadDir(assetsDir)
	if err != nil {
		return nil, fmt.Errorf("failed to read %s: %w", assetsDir, err)
	}

	result := &generationResult{generated: map[string][]byte{}}
	seenExcluded := map[string]bool{}
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		componentDir := filepath.Join(assetsDir, entry.Name())

		sourceFile, err := sourceMonitorFile(componentDir)
		if err != nil {
			return nil, err
		}

		outputPath := filepath.Join(generatedDir, entry.Name(), generatedPodMonitoring)
		if _, ok := excluded[entry.Name()]; ok {
			if sourceFile == "" {
				return nil, fmt.Errorf("%s is excluded from GMP generation but has no %s or %s; remove it from excludedComponents", componentDir, sourceServiceMonitor, sourcePodMonitor)
			}
			seenExcluded[entry.Name()] = true
			if isGeneratedFile(outputPath) {
				result.stale = append(result.stale, outputPath)
			}
			continue
		}
		if sourceFile == "" {
			if isGeneratedFile(outputPath) {
				result.stale = append(result.stale, outputPath)
			}
			continue
		}
		if fileExists(outputPath) && !isGeneratedFile(outputPath) {
			return nil, fmt.Errorf("%s is hand-written, but %s has a CoreOS %s, so the generator owns its PodMonitoring; delete the file to generate it, or add the component to excludedComponents", outputPath, componentDir, sourceFile)
		}

		data, err := generateComponent(componentDir, sourceFile)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", componentDir, err)
		}
		result.generated[outputPath] = data
	}

	for name := range excluded {
		if !seenExcluded[name] {
			return nil, fmt.Errorf("excluded component %q has no directory under %s; remove it from excludedComponents", name, assetsDir)
		}
	}

	// A removed source component no longer appears in the input walk, so scan
	// the output tree as well to catch its previously generated manifest.
	outputEntries, err := os.ReadDir(generatedDir)
	if err != nil && !os.IsNotExist(err) {
		return nil, fmt.Errorf("failed to read %s: %w", generatedDir, err)
	}
	for _, entry := range outputEntries {
		if !entry.IsDir() {
			continue
		}
		outputPath := filepath.Join(generatedDir, entry.Name(), generatedPodMonitoring)
		if _, expected := result.generated[outputPath]; expected {
			continue
		}
		if isGeneratedFile(outputPath) {
			result.stale = append(result.stale, outputPath)
		}
	}

	sort.Strings(result.stale)
	result.stale = compactPaths(result.stale)
	return result, nil
}

// sourceMonitorFile returns the CoreOS monitor asset in a component directory,
// or "" when the component does not expose metrics.
func sourceMonitorFile(componentDir string) (string, error) {
	serviceMonitor := fileExists(filepath.Join(componentDir, sourceServiceMonitor))
	podMonitor := fileExists(filepath.Join(componentDir, sourcePodMonitor))

	switch {
	case serviceMonitor && podMonitor:
		return "", fmt.Errorf("%s contains both %s and %s; a component may only declare one monitor", componentDir, sourceServiceMonitor, sourcePodMonitor)
	case serviceMonitor:
		return sourceServiceMonitor, nil
	case podMonitor:
		return sourcePodMonitor, nil
	default:
		return "", nil
	}
}

func fileExists(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}

// isGeneratedFile reports whether path exists and carries the generator header.
func isGeneratedFile(path string) bool {
	raw, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	return bytes.HasPrefix(raw, []byte("# Code generated by hack/gmp-config-gen"))
}

func writeResult(result *generationResult) {
	paths := sortedKeys(result.generated)
	for _, path := range paths {
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			fatal(fmt.Errorf("failed to create output directory for %s: %w", path, err))
		}
		if err := os.WriteFile(path, result.generated[path], 0o644); err != nil {
			fatal(fmt.Errorf("failed to write %s: %w", path, err))
		}
	}
	for _, path := range result.stale {
		if err := os.Remove(path); err != nil {
			fatal(fmt.Errorf("failed to remove stale %s: %w", path, err))
		}
	}
	fmt.Printf("gmp-config-gen: generated %d PodMonitoring manifest(s), removed %d stale file(s)\n", len(paths), len(result.stale))
}

func verifyResult(result *generationResult) {
	var outdated []string
	for _, path := range sortedKeys(result.generated) {
		committed, err := os.ReadFile(path)
		if err != nil || !bytes.Equal(committed, result.generated[path]) {
			outdated = append(outdated, path)
		}
	}
	outdated = append(outdated, result.stale...)

	if len(outdated) == 0 {
		fmt.Println("gmp-config-gen: generated PodMonitoring manifests are up to date")
		return
	}
	sort.Strings(outdated)
	fmt.Fprintln(os.Stderr, "generated GMP PodMonitoring manifests are out of date:")
	for _, path := range outdated {
		fmt.Fprintf(os.Stderr, "  %s\n", displayPath(path))
	}
	fmt.Fprintln(os.Stderr, "Run 'make generate-gmp-config', review the generated changes and commit them.")
	os.Exit(1)
}

// displayPath prints paths relative to the working directory, which is the
// repository root under make, so CI output points at the file to commit.
func displayPath(path string) string {
	cwd, err := os.Getwd()
	if err != nil {
		return path
	}
	relative, err := filepath.Rel(cwd, path)
	if err != nil {
		return path
	}
	return relative
}

func sortedKeys(generated map[string][]byte) []string {
	paths := make([]string, 0, len(generated))
	for path := range generated {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	return paths
}

// generateComponent converts the CoreOS monitor in componentDir into the
// committed GMP PodMonitoring document.
func generateComponent(componentDir, sourceFile string) ([]byte, error) {
	placeholders := newTemplatePlaceholders()

	raw, err := os.ReadFile(filepath.Join(componentDir, sourceFile))
	if err != nil {
		return nil, err
	}
	prepared := placeholders.protect(raw)

	component, err := loadComponent(componentDir, placeholders)
	if err != nil {
		return nil, err
	}

	var doc *podMonitoringDoc
	switch sourceFile {
	case sourceServiceMonitor:
		monitor := &prometheusServiceMonitor{}
		if err := strictUnmarshal(prepared, monitor); err != nil {
			return nil, fmt.Errorf("failed to parse %s: %w", sourceFile, err)
		}
		doc, err = component.convertServiceMonitor(monitor)
	case sourcePodMonitor:
		monitor := &prometheusPodMonitor{}
		if err := strictUnmarshal(prepared, monitor); err != nil {
			return nil, fmt.Errorf("failed to parse %s: %w", sourceFile, err)
		}
		doc, err = component.convertPodMonitor(monitor)
	}
	if err != nil {
		return nil, fmt.Errorf("%s: %w", sourceFile, err)
	}

	output, err := marshalDoc(doc, filepath.Base(componentDir), sourceFile)
	if err != nil {
		return nil, err
	}
	return placeholders.restore(output), nil
}

// marshalDoc encodes the document with a stable two-space layout and the
// generated-file header.
func marshalDoc(doc *podMonitoringDoc, componentName, sourceFile string) ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteString(generatedHeader)
	fmt.Fprintf(&buf, "# Source: v2/assets/%s/%s\n\n", componentName, sourceFile)
	encoder := newYAMLEncoder(&buf)
	if err := encoder.Encode(doc); err != nil {
		return nil, err
	}
	if err := encoder.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// compactPaths removes duplicate stale paths found during both input and output walks.
func compactPaths(paths []string) []string {
	if len(paths) == 0 {
		return paths
	}
	out := paths[:1]
	for _, path := range paths[1:] {
		if path != out[len(out)-1] {
			out = append(out, path)
		}
	}
	return out
}
